'use strict';

const LETTER_BASE = 'a'.charCodeAt(0);
const DIGIT_CODES = {
  '1': 0x1e,
  '2': 0x1f,
  '3': 0x20,
  '4': 0x21,
  '5': 0x22,
  '6': 0x23,
  '7': 0x24,
  '8': 0x25,
  '9': 0x26,
  '0': 0x27
};

const KEY_CODES = {
  enter: 0x28,
  return: 0x28,
  escape: 0x29,
  esc: 0x29,
  backspace: 0x2a,
  tab: 0x2b,
  space: 0x2c,
  '-': 0x2d,
  '=': 0x2e,
  '[': 0x2f,
  ']': 0x30,
  '\\': 0x31,
  ';': 0x33,
  "'": 0x34,
  '`': 0x35,
  ',': 0x36,
  '.': 0x37,
  '/': 0x38,
  up: 0x52,
  down: 0x51,
  right: 0x4f,
  left: 0x50
};

const MODIFIER_MASKS = {
  control: 0x01,
  ctrl: 0x01,
  shift: 0x02,
  alt: 0x04,
  option: 0x04,
  command: 0x08,
  cmd: 0x08,
  meta: 0x08
};

function normalizeKey(key) {
  return String(key || '').trim().toLowerCase();
}

function getKeyCode(key) {
  const normalized = normalizeKey(key);
  if (!normalized) return 0;

  if (normalized.length === 1 && normalized >= 'a' && normalized <= 'z') {
    return 0x04 + (normalized.charCodeAt(0) - LETTER_BASE);
  }

  if (DIGIT_CODES[normalized]) {
    return DIGIT_CODES[normalized];
  }

  return KEY_CODES[normalized] || 0;
}

function getModifierMask(key) {
  return MODIFIER_MASKS[normalizeKey(key)] || 0;
}

function isModifierKey(key) {
  return getModifierMask(key) !== 0;
}

module.exports = {
  getKeyCode,
  getModifierMask,
  isModifierKey
};
